 await page.screenshot({path:path.join(dir,'dashboard-desktop.png'),fullPage:true});await page.locator('#host-metrics > summary').click();await page.locator('#host-metrics svg').nth(2).waitFor();assert.equal(await page.locator('#host-metrics svg').count(),3);await page.locator('#host-metrics > summary').click();await Promise.all([page.waitForResponse(r=>new URL(r.url()).pathname==='/api/v1/sites'),page.locator('#dashboard-domain-details > summary').click()]);await page.locator('#domain-overview').waitFor();assert.ok(calls.includes('/sites'));await page.locator('#dashboard-domain-details > summary').click();
 degraded=true;await page.getByRole('button',{name:'Обновить сводку',exact:true}).click();await page.getByText('Репликация требует внимания',{exact:true}).waitFor();assert.equal(await page.locator('.replication-details').evaluate(e=>e.open),true,'problems must remain visible');
 degraded=false;await page.getByRole('button',{name:'Обновить сводку',exact:true}).click();await page.getByText('Репликация в порядке',{exact:true}).waitFor();await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await page.screenshot({path:path.join(dir,'dashboard-mobile.png'),fullPage:true});
